mapper.select:
select id, session_id, user_id, role, content, sequence, status,
       generation_task_id, request_id, model_id, error_code, error_message,
       create_time, update_time, deleted
from chat_message
where session_id = #{sessionId}
  and user_id = #{userId}
  and deleted = 0
  and status in ('COMPLETED', 'STREAMING', 'PENDING', 'FAILED', 'INTERRUPTED')

    and sequence <= #{beforeSequence}

order by sequence asc, id asc

select coalesce(max(sequence), 0)
from chat_message
where session_id = #{sessionId}
  and user_id = #{userId}
  and deleted = 0

select id, session_id, user_id, role, content, sequence, status,
       generation_task_id, request_id, model_id, error_code, error_message,
       create_time, update_time, deleted
from chat_message
where session_id = #{sessionId}
  and user_id = #{userId}
  and sequence < #{sequence}
  and role = #{role}
  and deleted = 0
order by sequence desc, id desc
limit 1
